 script={'a_cpu':'cpu_probe.py','a_emp':'empirical_probe.py','a_software':'software_probe.py','a_browser':'browser_probe.py','a_features':'browser_features.py','a_pub':'publication_probe.py'}[id]
 artifact(id,'execution',name,description,'.venv/bin/python '+base+script,'Completed with exit code 0; assertions and the expected/observed comparisons are retained in this artifact and corresponding stdout/stderr.')
 artifact(id+'_script','code',script,'Exact independently written bounded probe used for '+id)
 stem={'a_cpu':'cpu','a_emp':'empirical','a_software':'software','a_browser':'browser','a_features':'browser-features','a_pub':'publication'}[id]
 for ext in ['stdout.txt','stderr.txt']:artifact(id+'_'+ext.replace('.','_'),'source_snapshot',stem+'.'+ext,'Raw '+ext+' from the successful '+id+' command; stderr is retained even when empty.')
