def original(id,name,kind,title,version,locator,note,authority):
 r=retrieval[name]
 row={'id':id,'kind':kind,'title':title,'url':r['url'],'version':version,'verified':True,'checked_original':True,'accessed_on':r['accessed_on'],'authority_reason':authority,'inspection_note':locator+' — '+note,'retrieval_sha256':r['sha256'],'raw_retrieval_path':'outputs/natural-v4/factual-research/entries/'+name}
 sources.append(row)
 return id
