def add(id,kind,statement,location,scope,evidence,artifacts_used,expected=None,observed=None,details=None,status='verified',denom=None):
 row={'id':id,'kind':kind,'statement':statement,'location':location,'status':status,'scope':scope,'evidence':[{'source_id':s,'locator':l,'supports':support} for s,l,support in evidence],'artifact_ids':artifacts_used}
 if kind!='concept':
  row['verification']={'method':'executed','expected':expected,'observed':observed,'details':details}
  if kind=='numeric':row['verification']['tolerance']='Exact integer/byte equality; stated one-decimal MiB value uses rounding to nearest 0.1 MiB.'
  if kind=='empirical':row['verification']['denominators']=denom
 claims.append(row)
